"""Generate documentation only. Never connects to a database or executes SQL."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
T=[]
def add(name,phase,grain,fields,keys='',rules='',mode='mutable',global_=False):
    cols=[dict(name='id',type='uuid',nullable=False,reference=None)]
    if not global_ and name!='org.companies': cols.append(dict(name='company_id',type='uuid',nullable=False,reference='org.companies.id'))
    for spec in fields.split(';'):
        if not spec.strip():continue
        pair=spec.strip().split('=',1); left=pair[0].split(':',1)
        field,typ=left[0],left[1]; nullable=typ.endswith('?');typ=typ.rstrip('?')
        cols.append(dict(name=field,type=typ,nullable=nullable,reference=pair[1] if len(pair)>1 else None))
    cols.append(dict(name='created_at',type='timestamptz',nullable=False,reference=None))
    if mode=='mutable':cols += [dict(name='updated_at',type='timestamptz',nullable=False,reference=None),dict(name='version',type='integer',nullable=False,reference=None)]
    T.append(dict(name=name,phase=phase,grain=grain,mode=mode,columns=cols,keys=keys,rules=(rules or 'ใช้กฎ tenant, FK และ audit กลาง') + ('; structured Thai address: composite geography FKs + postal mapping ตาม 07-address-model.md' if name in {'org.companies','org.branches','catalog.supplier_addresses'} else '')))
