# Validate all internal references and write deterministic docs.
by={t['name']:t for t in T}
assert len(by)==len(T)
for t in T:
    assert len({c['name'] for c in t['columns']})==len(t['columns']),t['name']
    for c in t['columns']:
        if c['reference']:
            table,col=c['reference'].rsplit('.',1)
            assert table in by,(t['name'],c)
            assert col in {x['name'] for x in by[table]['columns']},(t['name'],c)
from thai_comments import annotate
annotate(T)
(ROOT/'model.catalog.json').write_text(json.dumps({'status':'DESIGN_ONLY_NOT_MIGRATION','tables':T},ensure_ascii=False,indent=2)+'\n')
lines=['# พจนานุกรมข้อมูล HOTPOTMAN ทั้งระบบ','','สถานะ: แบบออกแบบ ยังไม่ได้สร้างฐานข้อมูลหรือรัน Migration','',f'รวม {len(T)} ตารางเชิงตรรกะ แบ่งสร้างตามเฟส ไม่ใช่ข้อกำหนดให้สร้างทั้งหมดในวันแรก','',
'## วิธีอ่าน','','- `F` Foundation, `P` Purchasing/Delivery Phase 1, `W` Weighing/Warehouse, `O` Operations, `R` Reporting/Integration delivery; ดูแผนใน 04-migration-and-acceptance.md',
'- ทุกตารางมี `id uuid PK`; tenant table มี `company_id` และต้องมี `UNIQUE(company_id,id)` เพื่อใช้ composite FK กฎนี้รวมตาราง join ที่มี surrogate id',
'- `U` unique, `I` index; reference คอลัมน์แสดง FK target เชิงตรรกะ ใน implementation ต้องขยาย company_id ตามกฎ composite FK ใน 03-invariants-and-transactions.md',
'- เว้นแต่ระบุ `?`/nullable ในตาราง คอลัมน์เป็น NOT NULL; default id=UUID, created_at/updated_at=now(), version=1; ค่าอื่นต้องส่ง explicit หรือค่าที่ระบุใน policy ไม่เดา default',
'- Append table ไม่มี updated_at/version; ห้าม runtime update/delete business content ใช้ reversal ใหม่ ส่วน state-machine/projection เป็น mutable ตามกฎ',
'- JSON ใช้ snapshot/config/payload ที่ validate schema และ version ไม่ใช้แทน FK/จำนวน/เงินหลัก; address/locale text เป็นข้อมูลธุรกิจ ไม่ใช่คำสั่ง',
'- UUID ไม่รับประกัน tenant isolation; actor FK global user ต้องตรวจ membership ณ เวลา action และเก็บ audit เมื่อสิทธิ์เปลี่ยนภายหลัง',
'- FK ปริยาย `ON DELETE RESTRICT`; ไม่มี cascade ลบประวัติ เอกสาร immutable ตอน confirm/post แม้ระบุ mutable สำหรับ draft/state',
'- Field status/kind ใช้ text + CHECK allowlist ตาม 03; ไม่เปิดรับค่าอิสระจาก client',
'']
for t in T:
    lines += [f"## `{t['name']}`",'',f"**เฟส:** {t['phase']} · **หนึ่งแถวคือ:** {t['grain']} · **ประเภท:** {t['mode']}",'', f"**คำอธิบาย:** {t['comment_th']}", '', '| คอลัมน์ | PostgreSQL type | NULL | PK / FK | อ้างอิง | คำอธิบายภาษาไทย |','|---|---|---|---|---|---|']
    for c in t['columns']:
        lines += [f"| `{c['name']}` | `{c['type']}` | {'ได้' if c['nullable'] else 'ไม่ได้'} | {c['key_role']} | {('`'+c['reference']+'`') if c['reference'] else '—'} | {c['comment_th']} |"]
    lines += ['',f"**Keys / Index:** {t['keys'] or 'PK และ tenant FK ตามกฎกลาง'}",'',f"**กฎเฉพาะ:** {t['rules'] or 'ใช้กฎ tenant, FK และ audit กลาง'}",'']
(ROOT/'02-data-dictionary.md').write_text('\n'.join(lines).rstrip()+'\n')
print(f'{len(T)} tables; {sum(len(t["columns"]) for t in T)} columns; all FK references resolved')
